package vn.smartfarm.iot.irrigation;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.demo-enabled=false","smartfarm.irrigation.monitor-enabled=true","smartfarm.irrigation-queue.scheduling-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class CircuitMonitorPackageTest {
 @Autowired CircuitMonitorPackage packages;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 Map<String,String> before;
 @BeforeEach void setup(){clean();
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('PCWATER','Water','AREA001','WATER',2)");
  jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('PCWATER','LOW','WATER_PRESENT','boolean'),('PCWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,'Soil','AREA001','SOIL',2)","PCSOIL"+i);for(int c=1;c<=3;c++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","PCSOIL"+i,"SOIL"+c);
   jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,'Package zone','AREA001',?,'SIMULATOR',30,35)","PCZONE"+i,"PCSOIL"+i);circuits.create(config(i));}
  before=new TreeMap<>();for(String table:List.of("pump_command","watering_run","irrigation_demo_command","irrigation_queue_request","circuit_valve_status","circuit_valve_history","circuit_valve_alert"))before.put(table,rows(table));
 }
 void clean(){jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('PCTEST1','PCTEST2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('PCZONE1','PCZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('PCSOIL1','PCSOIL2','PCWATER')");}
 @AfterEach void cleanup(){try{for(var e:before.entrySet())assertEquals(e.getValue(),rows(e.getKey()),e.getKey());}finally{clean();}}
 String rows(String table){return jdbc.queryForObject("SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]')::text FROM "+table+" t",String.class);}
 ObjectNode config(int i){return mapper.createObjectNode().put("circuitId","PCTEST"+i).put("name","Package "+i).put("zoneId","PCZONE"+i).put("zoneRevision",1).put("controllerId","IRRIGATION0"+(i+6)).put("valveId","VALVE0"+(i+6)).put("pumpId","PUMP01").put("waterNodeId","PCWATER").put("lowChannelId","LOW").put("flowChannelId","FLOW").put("expectedSource","SIMULATOR");}
 CircuitMonitorPackage.Download export(int i){return packages.export("PCTEST"+i,1,1,"123456789012");}
 Map<String,byte[]> unzip(CircuitMonitorPackage.Download p)throws Exception{
  var result=new TreeMap<String,byte[]>();String prefix=p.filename().replace(".zip","")+"/";
  try(var zip=new ZipInputStream(new ByteArrayInputStream(p.bytes()),StandardCharsets.UTF_8)){ZipEntry e;while((e=zip.getNextEntry())!=null){assertTrue(e.getName().startsWith(prefix));assertFalse(e.getName().contains(".."));assertFalse(e.getName().contains("\\"));String name=e.getName().substring(prefix.length());assertNull(result.put(name,zip.readAllBytes()),"duplicate ZIP path");}}
  return result;
 }
 String text(Map<String,byte[]> files,String path){return new String(files.get(path),StandardCharsets.UTF_8);}
 @Test void completePackageHasOnlyExplicitPublicInputs()throws Exception{var f=unzip(export(1));var expected=new HashSet<>(CircuitMonitorPackage.PUBLIC_FILES);expected.addAll(List.of("data/.gitkeep",".gitignore","device-policy.json","backend-additional-identity-policy.json","manifest.json","README_VI.md"));assertEquals(expected,f.keySet());assertEquals(15,f.size());assertTrue(export(1).bytes().length<262144);assertFalse(f.containsKey("config/config.local.h"));}
 @Test void manifestHashesEveryOtherFileAndCapturesReviewedMapping()throws Exception{var f=unzip(export(1));var manifest=mapper.readTree(f.get("manifest.json"));assertEquals(1,manifest.path("packageVersion").asInt());assertEquals("IRRIGATION_MONITOR_ONLY",manifest.path("profile").asText());assertTrue(manifest.path("monitorOnly").asBoolean());assertFalse(manifest.path("provisioned").asBoolean());assertFalse(manifest.path("outputEnabled").asBoolean());assertEquals(mapper.valueToTree(circuits.find("PCTEST1")),manifest.path("circuit"));assertEquals(f.size()-1,manifest.path("filesSha256").size());for(var e:f.entrySet())if(!e.getKey().equals("manifest.json"))assertEquals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(e.getValue())),manifest.path("filesSha256").path(e.getKey()).asText());}
 @Test void configKeepsEndpointAndPasswordBlankAndForcesMonitorProfile()throws Exception{var f=unzip(export(1));var s=text(f,"config/config.example.h");for(String line:List.of("IRRIGATION_AWS_ENDPOINT \"\"","IRRIGATION_WIFI_PASSWORD \"\"","IRRIGATION_DEMO_ENABLED 0","IRRIGATION_MONITOR_ONLY 1","IRRIGATION_SIMULATOR 1","IRRIGATION_POSITION_FEEDBACK_ENABLED 1","IRRIGATION_CONTROLLER_ID \"IRRIGATION07\"","IRRIGATION_VALVE_ID \"VALVE07\"","IRRIGATION_CIRCUIT_ID \"PCTEST1\"","IRRIGATION_ZONE_ID \"PCZONE1\""))assertTrue(s.contains("#define "+line),line);assertEquals(0,f.get("data/.gitkeep").length);assertTrue(text(f,".gitignore").contains("config/config.local.h"));}
 @Test void sourceBytesAndBuildPinsComeFromCurrentPublicFirmware()throws Exception{var f=unzip(export(1));for(String path:List.of("src/main.cpp","include/ValveMonitor.h","include/ValveModel.h","platformio.ini","wokwi.toml"))try(var in=getClass().getResourceAsStream("/public-firmware/irrigation-monitor/"+path)){assertNotNull(in);assertArrayEquals(in.readAllBytes(),f.get(path));}assertTrue(text(f,"diagram.json").contains("VALVE07 monitor GPIO OFF"));assertFalse(text(f,"diagram.json").contains("VALVE01 GPIO only"));}
 @Test void devicePolicyHasOnlyOwnConnectAndStatusPublish()throws Exception{var f=unzip(export(1));var p=mapper.readTree(f.get("device-policy.json"));assertEquals(2,p.path("Statement").size());var connect=p.path("Statement").get(0);assertEquals("iot:Connect",connect.path("Action").asText());assertEquals("arn:aws:iot:ap-southeast-1:123456789012:client/IRRIGATION07",connect.path("Resource").asText());var publish=p.path("Statement").get(1);assertEquals("iot:Publish",publish.path("Action").asText());assertEquals("arn:aws:iot:ap-southeast-1:123456789012:topic/smartfarm/FARM001/VALVE07/status",publish.path("Resource").asText());assertFalse(p.toString().contains("*"));assertFalse(p.toString().contains("command"));assertFalse(p.toString().contains("RetainPublish"));}
 @Test void backendAdditionIsStatusSubscribeReceiveOnly()throws Exception{var p=mapper.readTree(unzip(export(1)).get("backend-additional-identity-policy.json"));assertEquals(Set.of("iot:Subscribe","iot:Receive"),new HashSet<>(List.of(p.path("Statement").get(0).path("Action").asText(),p.path("Statement").get(1).path("Action").asText())));for(var s:p.path("Statement"))assertTrue(s.path("Resource").asText().endsWith("/VALVE07/status"));assertFalse(p.toString().contains("iot:Publish"));assertFalse(p.toString().contains("*"));}
 @Test void policyJsonKeyOrderIsStableAcrossJvmMapIterationSeeds()throws Exception{var f=unzip(export(1));for(String path:List.of("device-policy.json","backend-additional-identity-policy.json")){String p=text(f,path);assertTrue(p.indexOf("\"Statement\"")<p.indexOf("\"Version\""));assertTrue(p.indexOf("\"Action\"")<p.indexOf("\"Effect\""));assertTrue(p.indexOf("\"Effect\"")<p.indexOf("\"Resource\""));}}
 @Test void separatePackagesNeverBorrowIdentity()throws Exception{var a=unzip(export(1));var b=unzip(export(2));assertTrue(text(a,"config/config.example.h").contains("\"IRRIGATION07\""));assertTrue(text(b,"config/config.example.h").contains("\"IRRIGATION08\""));assertFalse(text(a,"device-policy.json").contains("VALVE08"));assertFalse(text(b,"device-policy.json").contains("VALVE07"));}
 @Test void oldCircuitOrZoneReviewConflicts(){for(var revisions:List.of(new int[]{2,1},new int[]{1,2}))assertEquals(409,assertThrows(ResponseStatusException.class,()->packages.export("PCTEST1",revisions[0],revisions[1],"123456789012")).getStatusCode().value());}
 @Test void changedZoneAndWaterDeclarationCannotExport(){jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='PCZONE1'");assertEquals(409,assertThrows(ResponseStatusException.class,()->export(1)).getStatusCode().value());jdbc.update("UPDATE iot_channel SET metric='WATER_PRESSURE',unit='kPa' WHERE node_id='PCWATER' AND channel_id='FLOW'");assertEquals(409,assertThrows(ResponseStatusException.class,()->export(2)).getStatusCode().value());}
 @Test void sharedControllerRequiresSeparateClientId(){circuits.update("PCTEST2",((ObjectNode)mapper.valueToTree(circuits.find("PCTEST2"))).put("controllerId","IRRIGATION07"));assertEquals(409,assertThrows(ResponseStatusException.class,()->export(1)).getStatusCode().value());assertEquals(409,assertThrows(ResponseStatusException.class,()->packages.export("PCTEST2",2,1,"123456789012")).getStatusCode().value());}
 @Test void legacyAndPhysicalProfilesCannotBeExported(){circuits.update("PCTEST1",((ObjectNode)mapper.valueToTree(circuits.find("PCTEST1"))).put("controllerId","IRRIGATION01").put("valveId","VALVE01"));assertEquals(409,assertThrows(ResponseStatusException.class,()->packages.export("PCTEST1",2,1,"123456789012")).getStatusCode().value());jdbc.update("UPDATE irrigation_zone SET expected_source='PHYSICAL' WHERE zone_id='PCZONE2'");jdbc.update("UPDATE irrigation_circuit SET expected_source='PHYSICAL' WHERE circuit_id='PCTEST2'");assertEquals(409,assertThrows(ResponseStatusException.class,()->export(2)).getStatusCode().value());}
 @Test void inventoryCollisionBlocksPackage(){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('IRRIGATION07','Conflict','AREA001','WATER',2)");try{assertEquals(409,assertThrows(ResponseStatusException.class,()->export(1)).getStatusCode().value());}finally{jdbc.update("DELETE FROM iot_node WHERE node_id='IRRIGATION07'");}}
 @Test void invalidAccountRevisionAndPathCannotEnterTemplate(){for(String account:List.of("","123","1234567890123","12345678901\n","12345678901x","１２３４５６７８９０１２"))assertEquals(400,assertThrows(ResponseStatusException.class,()->packages.export("PCTEST1",1,1,account)).getStatusCode().value());assertEquals(400,assertThrows(ResponseStatusException.class,()->packages.export("../x",1,1,"123456789012")).getStatusCode().value());assertEquals(400,assertThrows(ResponseStatusException.class,()->packages.export("PCTEST1",0,1,"123456789012")).getStatusCode().value());assertEquals(404,assertThrows(ResponseStatusException.class,()->packages.export("UNKNOWN",1,1,"123456789012")).getStatusCode().value());}
 @Test void currentRevisionDownloadsAfterEditButPreviousReviewDoesNot()throws Exception{circuits.update("PCTEST1",((ObjectNode)mapper.valueToTree(circuits.find("PCTEST1"))).put("valveId","VALVE09"));assertEquals(409,assertThrows(ResponseStatusException.class,()->export(1)).getStatusCode().value());var p=packages.export("PCTEST1",2,1,"123456789012");assertTrue(p.filename().contains("r2-IRRIGATION07-VALVE09"));assertEquals(2,mapper.readTree(unzip(p).get("manifest.json")).path("circuit").path("revision").asInt());}
 @Test void downloadingDoesNotMutateAnyConfigurationOrRule()throws Exception{var watched=List.of("irrigation_circuit","irrigation_circuit_state","irrigation_zone","watering_rule","iot_node","iot_channel");var snapshot=new HashMap<String,String>();for(String t:watched)snapshot.put(t,rows(t));export(1);export(2);for(String t:watched)assertEquals(snapshot.get(t),rows(t),t);}
 @Test void httpDownloadUsesAttachmentNoStoreAndReviewedHeaders()throws Exception{var r=mvc.perform(get("/api/v1/irrigation-circuits/PCTEST1/monitor-package").param("accountId","123456789012").param("expectedRevision","1").param("expectedZoneRevision","1")).andExpect(status().isOk()).andExpect(content().contentType("application/zip")).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("X-Smartfarm-Package","IRRIGATION_MONITOR_V1")).andExpect(header().string("X-Smartfarm-Circuit","PCTEST1")).andExpect(header().string("X-Smartfarm-Controller","IRRIGATION07")).andReturn();assertTrue(r.getResponse().getHeader("Content-Disposition").contains("attachment"));assertEquals(15,unzip(new CircuitMonitorPackage.Download(export(1).filename(),circuits.find("PCTEST1"),r.getResponse().getContentAsByteArray())).size());}
 @Test void httpMissingOrInvalidReviewFailsInsteadOfServingOtherPackage()throws Exception{mvc.perform(get("/api/v1/irrigation-circuits/PCTEST1/monitor-package").param("accountId","123456789012")).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/irrigation-circuits/PCTEST1/monitor-package").param("accountId","123").param("expectedRevision","1").param("expectedZoneRevision","1")).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/irrigation-circuits/PCTEST1/monitor-package").param("accountId","123456789012").param("expectedRevision","2").param("expectedZoneRevision","1")).andExpect(status().isConflict());}
}
